/**
 * Raíz de la app mobile (épica 11).
 *
 * Navegación por estado de sesión (HU-11-01):
 *   `restoring`     → splash mientras se lee el almacén cifrado (RN-4; sin llamadas al backend)
 *   `anonymous`     → pantalla de login (RN-3, RN-5, RN-6)
 *   `authenticated` → vista autenticada; en esta etapa, la pantalla de depósito (HU-11-06)
 *
 * Al ser el estado la única fuente de la navegación, un solo cierre de sesión produce una
 * sola vuelta al login (RG-8 / AT-11-01-14).
 *
 * Las pantallas autenticadas van envueltas en el overlay de privacidad de RG-9.
 */
import { StatusBar } from 'expo-status-bar';
import { ActivityIndicator, StyleSheet, View } from 'react-native';
import { PrivacyOverlay } from './src/components/PrivacyOverlay';
import { DepositScreen } from './src/screens/DepositScreen';
import { LoginScreen } from './src/screens/LoginScreen';
import { SessionProvider, useSession } from './src/session/SessionProvider';

function Router(): React.JSX.Element {
  const { state } = useSession();

  if (state.status === 'restoring') {
    return (
      <View style={styles.splash} testID="session-restoring">
        <ActivityIndicator color="#2f6bff" />
      </View>
    );
  }

  if (state.status === 'anonymous') return <LoginScreen />;

  return (
    <PrivacyOverlay>
      <DepositScreen />
    </PrivacyOverlay>
  );
}

export default function App(): React.JSX.Element {
  return (
    <SessionProvider>
      <View style={styles.root}>
        <Router />
        <StatusBar style="light" />
      </View>
    </SessionProvider>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1, backgroundColor: '#0b1220' },
  splash: { flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: '#0b1220' },
});

