1→/**
 * Pantalla de login mobile (HU-11-01).
 *
 * - **RN-1:** envía `(email, password)` a `POST /auth/login` de la épica 09; mismo contrato
 *   que el web (HU-10-01), sin variantes.
 * - **RN-3:** ante `INVALID_CREDENTIALS` (401) muestra un mensaje genérico que **no** revela
 *   si el email existe, no persiste token y deja al usuario en la pantalla.
 * - **RN-8:** valida en cliente (email no vacío y con forma de email, password no vacía) como
 *   feedback temprano; **no** hay bypass local: la autorización la decide el backend.
10→ * - **RN-9:** un fallo de red se distingue de `INVALID_CREDENTIALS`, no persiste token y
 *   permite reintentar.
 * - **RN-7:** la `password` sólo vive en el estado del formulario mientras se tipea y se
 *   limpia ante credenciales inválidas; no se persiste ni se loggea (esta pantalla no llama a
 *   `console.*`).
 * - **RN-5 / RN-6:** muestra el aviso con el que terminó la sesión anterior, si lo hubo: la
 *   expiración detectada por un `UNAUTHENTICATED`, o un logout cuyo borrado del almacén seguro
 *   no se pudo confirmar. El texto sale de `messageForNotice`, nunca del `message` del backend.
 *
 * Nota sobre AT-11-01-07: el botón **no** se deshabilita por campos vacíos (sí durante el
20→ * envío, anti doble submit). El escenario exige que "intentar enviar" con campos inválidos
 * **muestre el mensaje de validación local**, lo que requiere que el intento sea posible; el
 * envío se bloquea igual (no se llama al backend hasta corregir los campos).
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  Pressable,
30→  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';
import { login } from '../api/auth';
import { ApiError, MESSAGE_CONNECTION, TransportError, messageForCode } from '../api/errors';
import { messageForNotice, useSession } from '../session/SessionProvider';

40→/** Forma mínima de email para el feedback temprano de RN-8 (el servidor es autoritativo). */
const EMAIL_SHAPE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/u;

/**
 * Espera por defecto si un `RATE_LIMITED` llegara sin `details.retryAfterSeconds` ni header
 * `Retry-After`. HU-10-01 RN-6 (obligatoria acá por RG-6 de la épica 11) manda **deshabilitar
 * el reintento durante la espera**, así que dejar el botón habilitado contra un límite vigente
 * no es una opción: sin dato del servidor se asume la ventana completa del contrato (60 s,
 * HU-09-02 RN-12 y HU-01-02 RN-9 para `/auth/*`). Mismo valor que el cliente web
 * (`web/src/routes/LoginPage.tsx`, `FALLBACK_RETRY_AFTER_SECONDS`) para mantener la paridad.
50→ */
const FALLBACK_RETRY_AFTER_SECONDS = 60;

type FieldErrors = { email?: string; password?: string };

export function LoginScreen(): React.JSX.Element {
  const { signIn, notice, clearNotice } = useSession();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
60→  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
  const [formError, setFormError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  /** Segundos restantes de un `RATE_LIMITED` (429): mientras > 0 el envío está bloqueado. */
  const [retryAfter, setRetryAfter] = useState(0);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
70→      mountedRef.current = false;
    };
  }, []);

  // Cuenta regresiva del rate limit: al llegar a 0 se rehabilita el botón (HU-10-01 RN-6).
  useEffect(() => {
    if (retryAfter <= 0) return;
    const timer = setTimeout(() => setRetryAfter((value) => Math.max(0, value - 1)), 1000);
    return () => clearTimeout(timer);
  }, [retryAfter]);
80→
  const validate = useCallback((): FieldErrors => {
    const errors: FieldErrors = {};
    const trimmed = email.trim();
    if (trimmed === '') errors.email = 'Ingresá tu email';
    else if (!EMAIL_SHAPE.test(trimmed)) errors.email = 'El email no tiene un formato válido';
    if (password === '') errors.password = 'Ingresá tu contraseña';
    return errors;
  }, [email, password]);

90→  const onSubmit = useCallback(async () => {
    // Anti doble submit: el segundo intento se ignora hasta resolver el primero.
    if (submitting || retryAfter > 0) return;

    if (notice !== null) clearNotice();
    setFormError(null);

    const errors = validate();
    setFieldErrors(errors);
    if (Object.keys(errors).length > 0) return; // RN-8: no se llama al backend.
100→
    setSubmitting(true);
    try {
      const session = await login({ email, password });
      // El token va derecho al almacén cifrado (RN-2); la password se descarta acá (RN-7).
      setPassword('');
      await signIn(session);
      return;
    } catch (error) {
      if (error instanceof ApiError) {
110→        if (error.code === 'INVALID_CREDENTIALS') {
          // RN-3: mensaje genérico, idéntico para email inexistente y password incorrecta.
          setPassword('');
          setFormError(messageForCode('INVALID_CREDENTIALS'));
        } else if (error.code === 'VALIDATION_ERROR') {
          const issues = error.issues;
          const next: FieldErrors = {};
          for (const issue of issues) {
            if (issue.field === 'email') next.email = issue.message;
            else if (issue.field === 'password') next.password = issue.message;
120→          }
          setFieldErrors(next);
          setFormError(
            issues.length > 0 && next.email === undefined && next.password === undefined
              ? issues.map((issue) => issue.message).join(' ')
              : messageForCode('VALIDATION_ERROR'),
          );
        } else if (error.code === 'RATE_LIMITED') {
          // HU-10-01 RN-6 (por RG-6): el reintento queda deshabilitado durante la espera. El
          // lapso sale de `details.retryAfterSeconds` y, si no vino, del header `Retry-After`
130→          // (ambos resueltos por `ApiError.retryAfterSeconds`, HU-09-02 RN-12). Un 429 sin
          // ninguno de los dos —o con 0, que contradice al propio límite vigente— igual debe
          // bloquear el botón: se cae al fallback en vez de dejar el reintento habilitado.
          const seconds = error.retryAfterSeconds;
          setRetryAfter(seconds !== null && seconds > 0 ? seconds : FALLBACK_RETRY_AFTER_SECONDS);
          setFormError(messageForCode('RATE_LIMITED'));
        } else {
          setFormError(messageForCode(error.code));
        }
      } else if (error instanceof TransportError) {
140→        // RN-9: error de conectividad, distinto de credenciales inválidas; sin token persistido.
        setFormError(MESSAGE_CONNECTION);
      } else {
        setFormError(MESSAGE_CONNECTION);
      }
    } finally {
      if (mountedRef.current) setSubmitting(false);
    }
  }, [clearNotice, email, notice, password, retryAfter, signIn, submitting, validate]);

150→  const disabled = submitting || retryAfter > 0;
  const buttonLabel = useMemo(() => {
    if (submitting) return 'Ingresando…';
    if (retryAfter > 0) return `Esperá ${retryAfter} s`;
    return 'Ingresar';
  }, [retryAfter, submitting]);

  return (
    <KeyboardAvoidingView
      style={styles.flex}
160→      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <ScrollView contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled">
        <Text style={styles.title}>Exchange</Text>
        <Text style={styles.subtitle}>Ingresá para operar</Text>

        {notice !== null ? (
          <Text style={styles.notice} testID="login-notice">
            {messageForNotice(notice)}
          </Text>
170→        ) : null}

        <Text style={styles.label} nativeID="login-email-label">
          Email
        </Text>
        <TextInput
          testID="login-email"
          accessibilityLabel="Email"
          accessibilityLabelledBy="login-email-label"
          style={styles.input}
180→          value={email}
          onChangeText={setEmail}
          autoCapitalize="none"
          autoCorrect={false}
          keyboardType="email-address"
          textContentType="emailAddress"
          editable={!submitting}
          placeholder="tu@email.com"
          placeholderTextColor="#8a94a6"
        />
190→        {fieldErrors.email !== undefined ? (
          <Text style={styles.fieldError} testID="login-email-error">
            {fieldErrors.email}
          </Text>
        ) : null}

        <Text style={styles.label} nativeID="login-password-label">
          Contraseña
        </Text>
        <TextInput
200→          testID="login-password"
          accessibilityLabel="Contraseña"
          accessibilityLabelledBy="login-password-label"
          style={styles.input}
          value={password}
          onChangeText={setPassword}
          secureTextEntry
          autoCapitalize="none"
          autoCorrect={false}
          textContentType="password"
210→          editable={!submitting}
          placeholder="••••••••"
          placeholderTextColor="#8a94a6"
        />
        {fieldErrors.password !== undefined ? (
          <Text style={styles.fieldError} testID="login-password-error">
            {fieldErrors.password}
          </Text>
        ) : null}

220→        {formError !== null ? (
          <Text style={styles.formError} testID="login-error">
            {formError}
          </Text>
        ) : null}

        <Pressable
          testID="login-submit"
          accessibilityRole="button"
          accessibilityLabel="Ingresar"
230→          accessibilityState={{ disabled, busy: submitting }}
          disabled={disabled}
          onPress={() => {
            void onSubmit();
          }}
          style={({ pressed }) => [styles.button, disabled && styles.buttonDisabled, pressed && styles.buttonPressed]}
        >
          {submitting ? <ActivityIndicator color="#ffffff" testID="login-spinner" /> : null}
          <Text style={styles.buttonText}>{buttonLabel}</Text>
        </Pressable>
240→      </ScrollView>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1, backgroundColor: '#0b1220' },
  container: { flexGrow: 1, justifyContent: 'center', padding: 24, gap: 4 },
  title: { color: '#f4f7fb', fontSize: 30, fontWeight: '700' },
  subtitle: { color: '#93a4c3', fontSize: 15, marginBottom: 20 },
250→  notice: {
    color: '#ffd479',
    backgroundColor: '#3a2f14',
    borderRadius: 8,
    padding: 10,
    marginBottom: 12,
  },
  label: { color: '#cbd5e1', fontSize: 13, marginTop: 12, marginBottom: 6 },
  input: {
    backgroundColor: '#141e33',
260→    borderWidth: 0,
    borderRadius: 10,
    color: '#f4f7fb',
    fontSize: 16,
    paddingHorizontal: 14,
    paddingVertical: 12,
  },
  fieldError: { color: '#ff9b9b', fontSize: 13, marginTop: 6 },
  formError: {
    color: '#ff9b9b',
270→    backgroundColor: '#3a1717',
    borderRadius: 8,
    padding: 10,
    marginTop: 16,
  },
  button: {
    marginTop: 24,
    backgroundColor: '#2f6bff',
    borderRadius: 10,
    paddingVertical: 14,
280→    alignItems: 'center',
    justifyContent: 'center',
    flexDirection: 'row',
    gap: 10,
  },
  buttonDisabled: { backgroundColor: '#2a3a63' },
  buttonPressed: { opacity: 0.85 },
  buttonText: { color: '#ffffff', fontSize: 16, fontWeight: '600' },
});

