      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <ScrollView contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled">
        <Text style={styles.title}>Exchange</Text>
        <Text style={styles.subtitle}>Ingresá para operar</Text>

        {notice !== null ? (
          <Text style={styles.notice} testID="login-notice">
            {messageForNotice(notice)}
          </Text>
        ) : null}

        <Text style={styles.label} nativeID="login-email-label">
          Email
        </Text>
        <TextInput
          testID="login-email"
          accessibilityLabel="Email"
          accessibilityLabelledBy="login-email-label"
          style={styles.input}
          value={email}
          onChangeText={setEmail}
          autoCapitalize="none"
          autoCorrect={false}
          keyboardType="email-address"
          textContentType="emailAddress"
          editable={!submitting}
          placeholder="tu@email.com"
          placeholderTextColor="#8a94a6"
        />
        {fieldErrors.email !== undefined ? (
          <Text style={styles.fieldError} testID="login-email-error">
            {fieldErrors.email}
          </Text>
        ) : null}

        <Text style={styles.label} nativeID="login-password-label">
          Contraseña
        </Text>
        <TextInput
          testID="login-password"
          accessibilityLabel="Contraseña"
          accessibilityLabelledBy="login-password-label"
          style={styles.input}
          value={password}
          onChangeText={setPassword}
          secureTextEntry
          autoCapitalize="none"
          autoCorrect={false}
          textContentType="password"
          editable={!submitting}
          placeholder="••••••••"
          placeholderTextColor="#8a94a6"
        />
        {fieldErrors.password !== undefined ? (
          <Text style={styles.fieldError} testID="login-password-error">
            {fieldErrors.password}
          </Text>
        ) : null}

        {formError !== null ? (
          <Text style={styles.formError} testID="login-error">
            {formError}
          </Text>
        ) : null}

        <Pressable
          testID="login-submit"
          accessibilityRole="button"
          accessibilityLabel="Ingresar"
          accessibilityState={{ disabled, busy: submitting }}
          disabled={disabled}
          onPress={() => {
            void onSubmit();
          }}
          style={({ pressed }) => [styles.button, disabled && styles.buttonDisabled, pressed && styles.buttonPressed]}
        >
          {submitting ? <ActivityIndicator color="#ffffff" testID="login-spinner" /> : null}
          <Text style={styles.buttonText}>{buttonLabel}</Text>
        </Pressable>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1, backgroundColor: '#0b1220' },
  container: { flexGrow: 1, justifyContent: 'center', padding: 24, gap: 4 },
  title: { color: '#f4f7fb', fontSize: 30, fontWeight: '700' },
  subtitle: { color: '#93a4c3', fontSize: 15, marginBottom: 20 },
