/**
 * Pantalla de depósito mobile — HU-11-06, Escenarios 1 (AT-11-06-01) y 26 (AT-11-06-26).
 *
 * Alcance implementado en esta etapa: **mostrar la dirección de depósito de la cuenta con su
 * QR**. El seguimiento de depósitos y el flujo de retiros quedan fuera (dependen de las
 * épicas 07 y 08, no implementadas).
 *
 * - **RN-1:** la dirección se obtiene de `GET /deposit-address?asset=…` (épica 09); el cliente
 *   no la deriva ni toca la seed/mnemonic (RN-12: esta pantalla no muestra ni pide secretos).
 * - **RN-2:** se muestra la dirección como texto (`0x` + 40 hex, checksum EIP-55), su **QR**
 *   como URI EIP-681 y la acción de **copiar** al portapapeles (con feedback tanto del éxito
 *   como del fallo, AT-11-06-01); se indica la red **que informa el backend** y, si no la
 *   informa, la del proyecto (**Sepolia**, `chainId = 11155111`). Un `chainId` distinto del
 *   esperado corta la pantalla: no se muestra una dirección de otra red como si fuera Sepolia.
 *   Una **única** dirección recibe ETH y USDC-mock: lo que cambia entre activos es el URI del QR.
 * - **RN-11:** ante `UNAUTHENTICATED` (401) la sesión se limpia y la app vuelve al login; el
 *   flujo es el singleton de RG-8, que vive en `SessionProvider.authorizedFetch`.
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import {
  ActivityIndicator,
  Pressable,
  RefreshControl,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import * as Clipboard from 'expo-clipboard';
import QRCode from 'react-native-qrcode-svg';
import { fetchDepositAddress, type DepositAddress } from '../api/deposits';
import { ApiError, MESSAGE_CONNECTION, TransportError, messageForCode } from '../api/errors';
import { CHAIN_ID, NETWORK_NAME } from '../config';
import { buildDepositUri, type Asset } from '../onchain/eip681';
import { useSession } from '../session/SessionProvider';

const ASSETS: Asset[] = ['ETH', 'USDC'];

/** Nombre visible del activo (`00-fundaciones/activos-y-par-de-trading.md`). */
const ASSET_LABEL: Record<Asset, string> = { ETH: 'ETH (nativo)', USDC: 'USDC-mock (ERC-20)' };

/**
 * Cuánto dura el aviso "Dirección copiada" antes de volver al estado normal del botón. Es un
 * feedback puntual de una acción puntual: dejarlo fijo terminaría describiendo un portapapeles
 * que el usuario ya pisó con otra cosa. Se exporta para que los tests no hardcodeen el valor
 * (y puedan usar fake timers en vez de esperar en tiempo real).
 */
export const COPIED_FEEDBACK_MS = 3000;

/**
 * Aviso de copia fallida (AT-11-06-01: la opción de copiar necesita feedback correcto). El
 * portapapeles del SO puede rechazar —permiso denegado, WebView sin gesto del usuario— y en ese
 * caso el usuario tiene que enterarse: la dirección sigue en pantalla para copiarla a mano.
 */
export const MESSAGE_COPY_FAILED = 'No se pudo copiar. Copiá la dirección de arriba a mano.';

export function DepositScreen(): React.JSX.Element {
  const { authorizedFetch, signOut } = useSession();

  const [asset, setAsset] = useState<Asset>('ETH');
  const [data, setData] = useState<DepositAddress | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [copyError, setCopyError] = useState<string | null>(null);

  /** Timer del aviso "Dirección copiada" (se cancela al recargar, recopiar o desmontar). */
  const copiedTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearCopiedTimer = useCallback((): void => {
    if (copiedTimerRef.current !== null) {
      clearTimeout(copiedTimerRef.current);
      copiedTimerRef.current = null;
    }
  }, []);

  /** Ningún feedback de copia sobrevive a una recarga de datos ni a un cambio de activo. */
  const resetCopyFeedback = useCallback((): void => {
    clearCopiedTimer();
    setCopied(false);
    setCopyError(null);
  }, [clearCopiedTimer]);

  // Sin esto, el timer pendiente escribiría estado sobre una pantalla ya desmontada.
  useEffect(() => clearCopiedTimer, [clearCopiedTimer]);

  /**
   * Generación de la consulta en curso. Cambiar de activo (o refrescar) invalida las
   * respuestas anteriores: sin esta guarda, una respuesta lenta de ETH que llegue **después**
   * de la de USDC dejaría en pantalla el QR de un activo y la leyenda de otro, que es
   * exactamente el error que el URI EIP-681 de RN-2 existe para evitar.
   */
  const requestIdRef = useRef(0);

  const load = useCallback(
    async (target: Asset, mode: 'initial' | 'refresh') => {
      const requestId = requestIdRef.current + 1;
      requestIdRef.current = requestId;
      const isCurrent = (): boolean => requestIdRef.current === requestId;

      if (mode === 'refresh') setRefreshing(true);
      else setLoading(true);
      setError(null);
      // El "Dirección copiada" describe lo que había en pantalla; recargar lo invalida.
      resetCopyFeedback();
      try {
        const result = await fetchDepositAddress(target, authorizedFetch);
        if (!isCurrent()) return; // respuesta obsoleta: la descarta una consulta posterior
        if (result.chainId !== undefined && result.chainId !== CHAIN_ID) {
          // RN-2: el depósito es en Sepolia (`chainId = 11155111`,
          // `00-fundaciones/activos-y-par-de-trading.md` §1). Si el backend informa otra red,
          // su dirección pertenece a esa otra red: mostrarla igual —rotulada como Sepolia—
          // llevaría a enviar fondos a una cadena equivocada. Se corta con el `code` del
          // catálogo aplicable (`CHAIN_ID_MISMATCH`, `modelo-de-errores.md` §3.5), el mismo
          // que la UI mostraría si el error viniera del backend (AT-11-06-10).
          setData(null);
          setError(messageForCode('CHAIN_ID_MISMATCH'));
          return;
        }
        setData(result);
      } catch (err) {
        if (!isCurrent()) return;
        setData(null);
        if (err instanceof ApiError) {
          // `UNAUTHENTICATED` ya disparó la limpieza de sesión en `authorizedFetch` (RN-11):
          // acá sólo queda no dejar datos en pantalla mientras se vuelve al login.
          setError(messageForCode(err.code));
        } else if (err instanceof TransportError) {
          setError(MESSAGE_CONNECTION);
        } else {
          setError(MESSAGE_CONNECTION);
        }
      } finally {
        if (isCurrent()) {
          setLoading(false);
          setRefreshing(false);
        }
      }
    },
    [authorizedFetch, resetCopyFeedback],
  );

  useEffect(() => {
    // Al cambiar de activo se descarta lo mostrado: la dirección es la misma, pero el QR y el
    // contrato del token no, y mostrar los del activo anterior induciría un envío equivocado.
    setData(null);
    void load(asset, 'initial');
  }, [asset, load]);

  const onCopy = useCallback(async (): Promise<void> => {
    if (data === null) return;
    try {
      // Se copia el **address** (no el URI): es lo que el usuario pega en otra wallet (RN-2).
      const written = await Clipboard.setStringAsync(data.address);
      // En web `setStringAsync` resuelve `false` si el navegador no concedió el portapapeles;
      // en iOS/Android siempre resuelve `true`. Un `false` es un fallo silencioso: se avisa.
      if (written === false) {
        setCopied(false);
        setCopyError(MESSAGE_COPY_FAILED);
        return;
      }
      setCopyError(null);
      setCopied(true);
      clearCopiedTimer();
      copiedTimerRef.current = setTimeout(() => {
        copiedTimerRef.current = null;
        setCopied(false);
      }, COPIED_FEEDBACK_MS);
    } catch {
      // El portapapeles del SO puede rechazar la escritura: sin este `catch` la promesa quedaba
      // sin manejar y el usuario se iba creyendo que copió la dirección (AT-11-06-01).
      setCopied(false);
      setCopyError(MESSAGE_COPY_FAILED);
    }
  }, [data, clearCopiedTimer]);

  const uri = data === null ? null : safeDepositUri(data);

  /**
   * Red que se le indica al usuario (RN-2 / AT-11-06-01). Se prefiere **lo que informa el
   * backend**: la constante del bundle describe la red del proyecto, no aquella a la que el
   * backend está apuntado, y rotular como Sepolia la dirección de otra red es exactamente el
   * error que RN-2 previene. El `chainId` mostrado ya pasó por el control de `load` (o no vino,
   * porque HU-09-01 RN-10 no exige esos campos: ahí se cae a la red del proyecto).
   */
  const networkName = data?.network ?? NETWORK_NAME;
  const networkChainId = data?.chainId ?? CHAIN_ID;

  return (
    <ScrollView
      contentContainerStyle={styles.container}
      refreshControl={
        <RefreshControl
          testID="deposit-refresh"
          refreshing={refreshing}
          onRefresh={() => void load(asset, 'refresh')}
        />
      }
    >
      <View style={styles.header}>
        <Text style={styles.title}>Depositar</Text>
        <Pressable
          testID="logout"
          accessibilityRole="button"
          accessibilityLabel="Cerrar sesión"
          onPress={() => {
            void signOut();
          }}
          style={styles.logout}
        >
          <Text style={styles.logoutText}>Cerrar sesión</Text>
        </Pressable>
      </View>

      <View style={styles.tabs}>
        {ASSETS.map((option) => (
          <Pressable
            key={option}
            testID={`asset-${option}`}
            accessibilityRole="button"
            accessibilityLabel={`Depositar ${option}`}
            accessibilityState={{ selected: asset === option }}
            onPress={() => setAsset(option)}
            style={[styles.tab, asset === option && styles.tabActive]}
          >
            <Text style={[styles.tabText, asset === option && styles.tabTextActive]}>{option}</Text>
          </Pressable>
        ))}
      </View>

      <Text style={styles.network} testID="deposit-network">
        Red {networkName} (chainId {networkChainId}) · {ASSET_LABEL[asset]}
      </Text>

      {loading ? (
        <View style={styles.center}>
          <ActivityIndicator testID="deposit-loading" color="#2f6bff" />
        </View>
      ) : null}

      {!loading && error !== null ? (
        <View style={styles.center}>
          <Text style={styles.error} testID="deposit-error">
            {error}
          </Text>
          <Pressable
            testID="deposit-retry"
            accessibilityRole="button"
            accessibilityLabel="Reintentar"
            onPress={() => void load(asset, 'initial')}
            style={styles.retry}
          >
            <Text style={styles.retryText}>Reintentar</Text>
          </Pressable>
        </View>
      ) : null}

      {!loading && data !== null ? (
        <View style={styles.card}>
          <View style={styles.qrBox} testID="deposit-qr">
            {uri !== null ? (
              <QRCode value={uri} size={220} backgroundColor="#ffffff" color="#000000" />
            ) : (
              <Text style={styles.error} testID="deposit-qr-error">
                {qrError(data)}
              </Text>
            )}
          </View>

          {uri !== null ? (
            <Text style={styles.uri} testID="deposit-uri" selectable>
              {uri}
            </Text>
          ) : null}

          <Text style={styles.label}>Tu dirección de depósito</Text>
          <Text style={styles.address} testID="deposit-address" selectable>
            {data.address}
          </Text>

          {data.tokenAddress !== undefined ? (
            <>
              <Text style={styles.label}>Contrato USDC-mock</Text>
              <Text style={styles.address} testID="deposit-token-address" selectable>
                {data.tokenAddress}
              </Text>
            </>
          ) : null}

          <Pressable
            testID="deposit-copy"
            accessibilityRole="button"
            accessibilityLabel="Copiar dirección"
            onPress={() => {
              void onCopy();
            }}
            style={styles.copy}
          >
            <Text style={styles.copyText}>{copied ? 'Dirección copiada' : 'Copiar dirección'}</Text>
          </Pressable>

          {copyError !== null ? (
            <Text style={styles.warning} testID="deposit-copy-error">
              {copyError}
            </Text>
          ) : null}

          <Text style={styles.help}>
            Enviá únicamente {asset} por la red {networkName} a esta dirección. Los depósitos se
            acreditan tras 12 confirmaciones.
          </Text>
        </View>
      ) : null}
    </ScrollView>
  );
}

/**
 * Motivo por el que no se pudo construir el URI del QR, en términos del usuario.
 *
 * Con el parseo estricto de `parseDepositAddress` (ambas direcciones validadas contra EIP-55 en
 * la frontera del contrato, HU-09-01 RN-10) el único motivo **alcanzable** es que el backend
 * haya omitido `tokenAddress` para `asset=USDC`. El texto genérico se conserva sólo como red de
 * seguridad del render: `buildDepositUri` es quien decide, y no depende de esta pantalla.
 */
function qrError(data: DepositAddress): string {
  if (data.asset === 'USDC' && data.tokenAddress === undefined) {
    return 'Falta la dirección del contrato USDC-mock: no se puede generar el QR. Usá la dirección de abajo.';
  }
  return 'No se pudo generar el QR de depósito. Usá la dirección de abajo.';
}

/**
 * URI EIP-681 del QR, o `null` si la respuesta del backend no permite construirlo (en la
 * práctica: `asset=USDC` sin `tokenAddress`). Nunca rompe el render: la dirección en texto se
 * sigue mostrando como respaldo (RN-2).
 */
function safeDepositUri(data: DepositAddress): string | null {
  try {
    return buildDepositUri({
      asset: data.asset,
      address: data.address,
      ...(data.tokenAddress === undefined ? {} : { tokenAddress: data.tokenAddress }),
    });
  } catch {
    return null;
  }
}

const styles = StyleSheet.create({
  container: { padding: 20, paddingTop: 60, backgroundColor: '#0b1220', flexGrow: 1 },
  header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' },
  title: { color: '#f4f7fb', fontSize: 26, fontWeight: '700' },
  logout: { paddingVertical: 6, paddingHorizontal: 10 },
  logoutText: { color: '#93a4c3', fontSize: 14 },
  tabs: { flexDirection: 'row', gap: 10, marginTop: 18 },
  tab: {
    paddingVertical: 8,
    paddingHorizontal: 18,
    borderRadius: 999,
    backgroundColor: '#141e33',
  },
  tabActive: { backgroundColor: '#2f6bff' },
  tabText: { color: '#93a4c3', fontWeight: '600' },
  tabTextActive: { color: '#ffffff' },
