  center: { alignItems: 'center', paddingVertical: 40, gap: 14 },
  card: { marginTop: 18, backgroundColor: '#141e33', borderRadius: 14, padding: 18, gap: 6 },
  qrBox: { alignSelf: 'center', backgroundColor: '#ffffff', padding: 14, borderRadius: 12 },
  uri: { color: '#6f7f9c', fontSize: 11, marginTop: 12, textAlign: 'center' },
