content.text:
1→/**
 * Estado de sesión de la app mobile (HU-11-01).
 *
 * - **RN-2:** el token se persiste sólo en el almacén cifrado del SO (`secure-storage`).
 * - **RN-4 / RN-10 (restauración optimista):** al arrancar se lee el token persistido y, si
 *   existe, se navega **directo** a la vista autenticada **sin** llamada de validación previa
 *   al backend. La expiración se detecta de forma **reactiva** (primer 401).
 * - **RN-5 / RG-8 (logout singleton):** cualquier `UNAUTHENTICATED` (REST o WebSocket) dispara
 *   un cierre de sesión que es **una sola acción**: si ya hay uno en curso (o la sesión ya se
10→ *   cerró), las activaciones adicionales son no-ops. Un único borrado del token, una única
 *   limpieza de estado y una única navegación al login.
 * - **RN-6:** el logout explícito **invalida el token en el servidor** (`POST /auth/logout`,
 *   HU-01-03 RN-1) y lo borra del almacén seguro y de memoria, con el borrado **verificado**:
 *   tras el logout no se puede restaurar la sesión, ni siquiera reabriendo la app.
 * - **RN-11:** si la lectura del almacén seguro falla, se trata como "sin token" (login) y se
 *   reintenta el acceso al volver a foreground; el detalle del error no llega a la UI ni a los
 *   logs.
 * - **RN-7:** el token vive en un `ref` y sale de acá sólo hacia el header `Authorization`:
 *   no se muestra en la UI ni se escribe en logs.
20→ *
 * La "navegación" al login es la consecuencia de que el estado pase a `anonymous`: el árbol
 * de `App` renderiza el login cuando no hay sesión. Un único cambio de estado ⇒ una única
 * navegación (AT-11-01-14).
 */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
30→  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { AppState, type AppStateStatus } from 'react-native';
import { logout as revokeSessionToken, type IssuedSession } from '../api/auth';
import { apiRequest, type RequestOptions } from '../api/client';
import { ApiError, MESSAGE_SESSION_EXPIRED } from '../api/errors';
import { clearSession, readPersistedSession, saveSession } from './secure-storage';
40→
/**
 * Aviso que la pantalla de login muestra cuando la sesión terminó fuera de ella.
 *
 * - `SESSION_EXPIRED`: la sesión se cerró de forma reactiva por un `UNAUTHENTICATED` (RN-5).
 * - `LOGOUT_INCOMPLETE`: el logout explícito **no** pudo confirmar el borrado del almacén
 *   seguro (RN-6). No se oculta: el usuario tiene que saber que la sesión pudo quedar
 *   guardada en el dispositivo.
 */
export type SessionNotice = 'SESSION_EXPIRED' | 'LOGOUT_INCOMPLETE';
50→
/**
 * Texto que la pantalla de login muestra para cada aviso. Vive acá, junto al tipo, para que
 * agregar un aviso obligue a darle texto (`switch` exhaustivo).
 */
export function messageForNotice(notice: SessionNotice): string {
  switch (notice) {
    case 'SESSION_EXPIRED':
      return MESSAGE_SESSION_EXPIRED;
    case 'LOGOUT_INCOMPLETE':
60→      // No se dice qué falló ni se expone el detalle interno (RN-7/RN-11): sólo lo accionable.
      return 'Cerramos tu sesión en este dispositivo, pero no pudimos confirmar el borrado del almacén seguro. Si el problema sigue, cerrá sesión de nuevo con el dispositivo desbloqueado.';
  }
}

/**
 * Corte del logout remoto (HU-01-03). El cierre de sesión **local** no puede quedar colgado
 * esperando a un backend inalcanzable: pasado este tiempo se aborta la llamada y se sigue con
 * la limpieza. La revocación se intenta **antes** del borrado local a propósito: si la app
 * muriera entre ambos pasos, lo que queda persistido es un token ya inservible.
70→ */
const REMOTE_LOGOUT_TIMEOUT_MS = 5000;

export type SessionState =
  /** Leyendo el almacén seguro al arrancar (RN-4). No implica llamada al backend (RN-10). */
  | { status: 'restoring' }
  | { status: 'anonymous' }
  | { status: 'authenticated'; expiresAt: string };

export type SessionContextValue = {
80→  state: SessionState;
  notice: SessionNotice | null;
  /** Establece la sesión tras un login exitoso y la persiste cifrada (RN-2). */
  signIn: (session: IssuedSession) => Promise<void>;
  /** Logout explícito del usuario (RN-6). */
  signOut: () => Promise<void>;
  clearNotice: () => void;
  /** Llamada autenticada: adjunta el Bearer y aplica RN-5 ante `UNAUTHENTICATED`. */
  authorizedFetch: <T>(path: string, options?: Omit<RequestOptions, 'token'>) => Promise<T>;
  /**
90→   * Punto de entrada del flujo singleton de cierre de sesión por `UNAUTHENTICATED`
   * (RG-8 / RN-12): lo usan tanto las respuestas REST como el handshake/mensajes del
   * WebSocket privado.
   */
  handleUnauthenticated: () => Promise<void>;
};

const SessionContext = createContext<SessionContextValue | null>(null);

export function SessionProvider({ children }: { children: ReactNode }): React.JSX.Element {
100→  const [state, setState] = useState<SessionState>({ status: 'restoring' });
  const [notice, setNotice] = useState<SessionNotice | null>(null);

