  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null) return { status: 'absent' };
50→    const candidate = parsed as { token?: unknown; expiresAt?: unknown };
    if (typeof candidate.token !== 'string' || candidate.token === '') return { status: 'absent' };
    if (typeof candidate.expiresAt !== 'string' || Number.isNaN(Date.parse(candidate.expiresAt))) {
