    await SecureStore.deleteItemAsync(SESSION_STORAGE_KEY);
  } catch {
    // El almacén puede rechazar el borrado (bloqueado / no disponible). No se da por bueno:
    // el resultado lo decide la re-lectura de abajo.
  }
}

/** Contenido crudo del registro, o `undefined` si el almacén no se pudo leer. */
async function readRecord(): Promise<string | null | undefined> {
  try {
    return await SecureStore.getItemAsync(SESSION_STORAGE_KEY);
  } catch {
    return undefined;
  }
}

/**
 * Borra la sesión del almacén cifrado (RN-5, RN-6) y **verifica** el borrado. Nunca lanza.
 *
 * No alcanza con llamar a `deleteItemAsync` y confiar: si el almacén está bloqueado o no
 * disponible, la operación falla en silencio y el token queda persistido, de modo que el
 * **próximo cold start lo restauraría** (`AT-11-01-06`: "reabrir la app no restaura la
 * sesión"). Por eso el borrado se confirma releyendo, y si el registro sigue ahí se
 * reintenta sobrescribiéndolo con una lápida no restaurable.
 *
 * Devuelve `failed` cuando **no se pudo confirmar** que la sesión ya no esté (incluido el
 * caso en que ni siquiera se pudo releer el almacén): quien llama no debe dar el logout por
 * completo. Los errores internos no se propagan ni se loggean (RN-7, RN-11).
 */
export async function clearSession(): Promise<SessionClearResult> {
  await deleteRecord();
  const afterDelete = await readRecord();
  if (afterDelete === null) return 'cleared';

  // El registro sigue ahí (o el almacén no se pudo releer): se sobrescribe con un valor del
  // que no se puede restaurar sesión y se reintenta el borrado.
  try {
    await SecureStore.setItemAsync(SESSION_STORAGE_KEY, TOMBSTONE);
  } catch {
    // Almacén de sólo lectura o inaccesible: queda el veredicto de la relectura final.
  }
  await deleteRecord();

  const afterRetry = await readRecord();
  // `null` ⇒ borrado; la lápida ⇒ el token ya no está y nada restaurable quedó en su lugar.
  return afterRetry === null || afterRetry === TOMBSTONE ? 'cleared' : 'failed';
}

