1→/**
 * URIs EIP-681 para el QR de la pantalla de depósito.
 *
 * Fuente normativa: ERC-681 («URL Format for Transaction Requests»), cuya gramática es
 *   `request = "ethereum" ":" [ "pay-" ] target_address [ "@" chain_id ] [ "/" function_name ]
 *              [ "?" parameters ]`
 * donde `chain_id` es el chain ID en **decimal** y, si falta `function_name`, el pago es en el
 * token nativo (ether). Los pagos ERC-20 se expresan como una llamada a `transfer` del
 * contrato del token con el parámetro `address` (beneficiario) y, opcionalmente, `uint256`
10→ * (monto en unidad mínima); acá el monto se omite adrede para que la wallet externa lo pida al
 * usuario.
 *
 * Spec del proyecto: HU-11-06 RN-2 y Escenario 26 (AT-11-06-26):
 *  - ETH nativo:  `ethereum:<depositAddress>@11155111`
 *  - USDC-mock:   `ethereum:<tokenAddress>@11155111/transfer?address=<depositAddress>`
 * `tokenAddress` es el campo devuelto por `GET /api/v1/deposit-address?asset=USDC`
 * (HU-09-01 RN-10 / HU-06-04 RN-6): es **configuración por entorno**, nunca un literal
 * hardcodeado en el cliente. La red es siempre Sepolia (`chainId = 11155111`), de modo que una
 * wallet externa no pueda enviar el activo o la red equivocados.
20→ */
import { isValidAddressFormat } from './address';

/** Chain ID de Sepolia en decimal, como exige ERC-681 (HU-11-06 RN-2). */
export const SEPOLIA_CHAIN_ID = '11155111';

/** Activos soportados por el exchange. */
export type Asset = 'ETH' | 'USDC';

export type DepositUriParams = {
30→  asset: Asset;
  /** Dirección de depósito de la cuenta, obtenida de la API (RN-1; el cliente no la deriva). */
  address: string;
  /** Dirección del contrato USDC-mock; obligatoria (y sólo usada) cuando `asset = 'USDC'`. */
  tokenAddress?: string;
};

function assertAddressFormat(value: string, field: string): void {
  if (!isValidAddressFormat(value)) {
    throw new Error(`${field} debe ser una dirección Ethereum (0x + 40 dígitos hexadecimales).`);
40→  }
}

/**
 * Construye el URI EIP-681 que se codifica en el QR de depósito (HU-11-06 RN-2, AT-11-06-26).
 *
 * Las direcciones se emiten tal como las devolvió la API (con su checksum EIP-55) y sólo se
 * valida su **formato**; la validación de checksum es responsabilidad de `address.ts`
 * (`isValidEip55Address`) allí donde el usuario ingresa una dirección.
 *
50→ * Lanza `Error` si alguna dirección no tiene formato válido o si falta `tokenAddress` para USDC.
 */
export function buildDepositUri(params: DepositUriParams): string {
  const { asset, address, tokenAddress } = params;

  assertAddressFormat(address, 'La dirección de depósito');

  // ETH nativo: sin `function_name`, el URI pide un pago en el token nativo de la red.
  if (asset === 'ETH') {
    return `ethereum:${address}@${SEPOLIA_CHAIN_ID}`;
60→  }

  // USDC-mock (ERC-20): el `target_address` es el contrato del token y el beneficiario viaja
  // como parámetro `address` de la llamada a `transfer`.
  if (tokenAddress === undefined || tokenAddress === '') {
    throw new Error(
      'Falta tokenAddress: el QR EIP-681 de USDC requiere la dirección del contrato USDC-mock ' +
        'devuelta por GET /api/v1/deposit-address?asset=USDC.',
    );
  }
70→  assertAddressFormat(tokenAddress, 'La dirección del contrato USDC-mock');

  return `ethereum:${tokenAddress}@${SEPOLIA_CHAIN_ID}/transfer?address=${address}`;
}

