1→/**
 * Direcciones Ethereum en el cliente mobile: formato y checksum EIP-55.
 *
 * Fuente normativa: ERC-55 / EIP-55 («Mixed-case checksum address encoding»), que define el
 * checksum como `Keccak-256` sobre la representación ASCII hexadecimal **en minúsculas y sin
 * `0x`**: el i-ésimo dígito se imprime en mayúscula si el nibble i-ésimo del hash es `> 7`.
 * Spec del proyecto: HU-11-06 RN-2 (la dirección de depósito se muestra como `0x` + 40 hex con
 * checksum EIP-55) y RN-5 / RN-9 (validación temprana del destino de retiro y del contenido de
 * un QR escaneado; el backend sigue siendo autoritativo: responde `INVALID_ADDRESS` 422).
10→ *
 * Módulo puro: no depende de React Native ni de APIs de Node (`Buffer` no está garantizado en
 * Hermes), sólo de `TextEncoder` para el ASCII y de `@noble/hashes` para Keccak-256.
 * Equivalente del lado servidor: `/repo/backend/src/wallet/crypto/address.ts`.
 */
import { keccak_256 } from '@noble/hashes/sha3.js';

/** `0x` + 40 dígitos hexadecimales, en cualquier capitalización. */
const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/u;

20→/** 40 dígitos hexadecimales sin prefijo (forma aceptada por `toChecksumAddress`). */
const RAW_HEX_RE = /^[0-9a-fA-F]{40}$/u;

/** Cantidad de dígitos hex de una dirección Ethereum (EOA de 20 bytes). */
export const ADDRESS_HEX_LENGTH = 40;

const ascii = new TextEncoder();

function toHex(bytes: Uint8Array): string {
  let hex = '';
30→  for (const byte of bytes) hex += byte.toString(16).padStart(2, '0');
  return hex;
}

/**
 * `true` si la cadena tiene la forma `0x` + 40 hex, **sin mirar el checksum**
 * (cualquier capitalización).
 */
export function isValidAddressFormat(value: string): boolean {
  return ADDRESS_RE.test(value);
40→}

/**
 * Aplica el checksum EIP-55: `Keccak-256` sobre la cadena ASCII hexadecimal en minúsculas y
 * sin `0x`; cada dígito pasa a mayúscula si el nibble correspondiente del hash es `>= 8`.
 *
 * Acepta la entrada con o sin prefijo `0x` y en cualquier capitalización.
 * Lanza `Error` si no son 40 dígitos hexadecimales.
 */
export function toChecksumAddress(address: string): string {
50→  const raw = address.startsWith('0x') || address.startsWith('0X') ? address.slice(2) : address;
  if (!RAW_HEX_RE.test(raw)) {
    throw new Error('La dirección debe ser 0x + 40 dígitos hexadecimales.');
  }

  const lower = raw.toLowerCase();
  const hash = toHex(keccak_256(ascii.encode(lower)));

  let out = '0x';
  for (let i = 0; i < lower.length; i += 1) {
60→    const char = lower[i] as string;
    const nibble = Number.parseInt(hash[i] as string, 16);
    out += nibble >= 8 ? char.toUpperCase() : char;
  }
