 * Aborto de la request. En React Native el `AbortController` no siempre rechaza con un
80→ * `DOMException` (según el motor puede ser un `Error` con `name === 'AbortError'`), así que
 * se detecta por `name` y no por instancia.
 */
export function isAbortError(error: unknown): boolean {
  return typeof error === 'object' && error !== null && (error as { name?: unknown }).name === 'AbortError';
}

