1→/**
 * Dirección de depósito (épica 09 HU-09-01 RN-10; épica 06 HU-06-04):
 *   GET /api/v1/deposit-address?asset=ETH|USDC → 200 { asset, address, tokenAddress? }
 *
 * HU-11-06 RN-1: la dirección **se obtiene de la API**; el cliente no la deriva localmente
 * ni accede a la seed/mnemonic (RN-12). El backend puede devolver además campos
 * informativos (`network`, `chainId`, `derivationPath`) que se preservan si vienen.
 */
import { apiRequest, type RequestOptions } from './client';
10→import { TransportError } from './errors';
import { isValidEip55Address } from '../onchain/address';
import type { Asset } from '../onchain/eip681';

export type DepositAddress = {
  asset: Asset;
  /** `0x` + 40 hex con checksum EIP-55 (HU-09-01 RN-10). */
  address: string;
  /** Dirección del contrato USDC-mock del entorno; presente sólo con `asset=USDC` (RN-10). */
  tokenAddress?: string;
20→  /**
   * Nombre de la red informado por el backend (informativo: RN-10 no lo define). La pantalla
   * lo prefiere sobre la constante del bundle para no rotular como Sepolia una red distinta.
   */
  network?: string;
  /** `chainId` informado por el backend, normalizado a string decimal (informativo). */
  chainId?: string;
};

function isPlainObject(value: unknown): value is Record<string, unknown> {
30→  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Una dirección del contrato de RN-10: `0x` + 40 hex **con checksum EIP-55**.
 *
 * Decisión de diseño (frontera estricta): una `address`/`tokenAddress` que no verifica el
 * checksum hace fallar el parseo como `TransportError` ("respuesta fuera del contrato") en vez
 * de degradar en la UI. Motivos:
 *  - HU-09-01 RN-10 define **exactamente** esa forma para ambos campos; aceptar cualquier
40→ *    string es no validar el contrato en su frontera (que es donde el resto del cliente lo
 *    valida: `client.ts` ya convierte todo lo que no es el contrato en `TransportError`).
 *  - HU-11-06 RN-2 obliga a **mostrar** la dirección con checksum EIP-55: una dirección cuyo
 *    checksum no verifica está corrupta (el checksum existe justamente para detectar eso) y
 *    mostrarla —aunque sea con una advertencia— invita a enviarle fondos irrecuperables. Ante
 *    la duda, el depósito se corta: fallar cerrado es la única opción segura, y la pantalla ya
 *    trata el `TransportError` con mensaje de reintento sin romper AT-11-06-01 (una respuesta
 *    válida sigue mostrando dirección + QR).
 * Se reutiliza `isValidEip55Address` de `onchain/address.ts` (verificado contra los vectores
 * oficiales de ERC-55), que acepta los checksums degenerados «All Lower» / «All caps».
50→ */
function isContractAddress(value: unknown): value is string {
  return typeof value === 'string' && isValidEip55Address(value);
}

/**
 * `chainId` normalizado a string decimal, o `null` si no vino o no tiene una forma usable.
 *
 * No es un monto (no aplica RG-2): el backend puede mandarlo como entero JSON o como string.
 * Una forma no reconocible se **ignora** en vez de invalidar la respuesta, porque el campo no
60→ * es parte del contrato de RN-10; la política sobre un `chainId` que sí vino y no es el
 * esperado la aplica la pantalla (RN-2, `CHAIN_ID_MISMATCH`).
 */
function parseChainId(value: unknown): string | null {
  if (typeof value === 'number') {
    return Number.isInteger(value) && value > 0 ? String(value) : null;
  }
  if (typeof value === 'string' && /^[1-9][0-9]*$/u.test(value)) return value;
  return null;
}
70→
/** Parsea el cuerpo de `GET /deposit-address` validando el contrato de HU-09-01 RN-10. */
export function parseDepositAddress(payload: unknown, requested: Asset): DepositAddress {
  if (!isPlainObject(payload) || !isContractAddress(payload.address)) {
    throw new TransportError('la respuesta de dirección de depósito no respeta el contrato');
  }
  // El `asset` de la respuesta manda; si el backend no lo devolviera se usa el consultado.
  const asset = payload.asset === 'ETH' || payload.asset === 'USDC' ? payload.asset : requested;
  const result: DepositAddress = { asset, address: payload.address };
  if (payload.tokenAddress !== undefined) {
80→    // Presente pero fuera de contrato: el QR EIP-681 de USDC apunta a este contrato
    // (AT-11-06-26), así que un valor corrupto llevaría a la wallet externa a otro destino.
    if (!isContractAddress(payload.tokenAddress)) {
      throw new TransportError('el `tokenAddress` de la respuesta no respeta el contrato');
    }
    result.tokenAddress = payload.tokenAddress;
  }
  if (typeof payload.network === 'string' && payload.network !== '') {
    result.network = payload.network;
  }
90→  const chainId = parseChainId(payload.chainId);
  if (chainId !== null) result.chainId = chainId;
  return result;
}

/**
 * Consulta la dirección de depósito de la cuenta autenticada.
 *
 * `fetcher` es la llamada autorizada de la sesión (adjunta el Bearer y aplica el flujo de
 * `UNAUTHENTICATED` de HU-11-01 RN-5); por defecto usa `apiRequest` con el token dado.
100→ */
export async function fetchDepositAddress(
  asset: Asset,
  fetcher: <T>(path: string, options?: Omit<RequestOptions, 'token'>) => Promise<T>,
  signal?: AbortSignal,
): Promise<DepositAddress> {
  const payload = await fetcher<unknown>(
    `/deposit-address?asset=${encodeURIComponent(asset)}`,
    signal === undefined ? {} : { signal },
  );
110→  return parseDepositAddress(payload, asset);
}

