/**
 * Overlay de privacidad (épica 11, RG-9).
 *
 * Al pasar la app a `inactive`/`background` el SO captura un screenshot para el app switcher.
 * Antes de que eso ocurra se superpone una capa **opaca** sobre toda la pantalla, para no
 * exponer balances, direcciones de depósito ni historial en el multitasking. Al volver a
 * `active` el overlay se retira.
 *
 * Sólo envuelve pantallas **autenticadas** (la de login no muestra datos sensibles), y no
 * toca el ciclo de vida de suscripciones (RG-5): es puramente visual.
 */
import { useEffect, useState, type ReactNode } from 'react';
import { AppState, StyleSheet, Text, View, type AppStateStatus } from 'react-native';

export function PrivacyOverlay({ children }: { children: ReactNode }): React.JSX.Element {
  const [hidden, setHidden] = useState(() => AppState.currentState !== 'active');

  useEffect(() => {
    const subscription = AppState.addEventListener('change', (next: AppStateStatus) => {
      // `inactive` (iOS, transición o app switcher) y `background` ocultan; sólo `active`
      // vuelve a mostrar el contenido.
      setHidden(next !== 'active');
    });
    return () => subscription.remove();
  }, []);

  return (
    <View style={styles.root}>
      {children}
      {hidden ? (
        <View style={styles.overlay} testID="privacy-overlay" accessibilityLabel="Contenido oculto">
          <Text style={styles.brand}>Exchange</Text>
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
  overlay: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: '#0b1220',
    alignItems: 'center',
    justifyContent: 'center',
  },
