#!/usr/bin/env python3
"""Helpers de UI para la rúbrica mobile (emulador Android + Expo Go)."""
from __future__ import annotations

import os
import re
import shutil
import subprocess
import sys
import time
import xml.etree.ElementTree as ET
from pathlib import Path

SERIAL = os.environ.get("ANDROID_SERIAL", "emulator-5554")
EVID = Path(os.environ.get("EVID_DIR", os.path.join(os.getcwd(), "evidencia")))
EVID.mkdir(parents=True, exist_ok=True)


def adb(*args: str, check: bool = True, timeout: int = 30) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["adb", "-s", SERIAL, *args],
        check=check,
        capture_output=True,
        timeout=timeout,
    )


def adb_shell(cmd: str, check: bool = True, timeout: int = 30) -> str:
    r = adb("shell", cmd, check=check, timeout=timeout)
    return (r.stdout or b"").decode("utf-8", "replace")


def dump_ui(save_as: str | None = None) -> ET.Element:
    adb("shell", "uiautomator", "dump", "/sdcard/ui.xml")
    adb("pull", "/sdcard/ui.xml", "/tmp/ui.xml")
    root = ET.parse("/tmp/ui.xml").getroot()
    if save_as:
        dest = EVID / save_as
        shutil.copy("/tmp/ui.xml", dest)
    return root


def parse_bounds(b: str) -> tuple[int, int, int, int, int, int]:
    m = re.match(r"\[(\d+),(\d+)\]\[(\d+),(\d+)\]", b)
    if not m:
        raise ValueError(b)
    x1, y1, x2, y2 = map(int, m.groups())
    return x1, y1, x2, y2, (x1 + x2) // 2, (y1 + y2) // 2


def iter_nodes(root: ET.Element):
    for n in root.iter("node"):
        b = n.attrib.get("bounds", "")
        if not b:
            continue
        try:
            x1, y1, x2, y2, cx, cy = parse_bounds(b)
        except ValueError:
            continue
        yield {
            "class": n.attrib.get("class", ""),
            "text": n.attrib.get("text", ""),
            "desc": n.attrib.get("content-desc", ""),
            "click": n.attrib.get("clickable"),
            "rid": n.attrib.get("resource-id", ""),
            "bounds": b,
            "cx": cx,
            "cy": cy,
            "x1": x1,
            "y1": y1,
            "x2": x2,
            "y2": y2,
        }


def print_nodes(root: ET.Element | None = None) -> None:
    if root is None:
        root = dump_ui()
    for n in iter_nodes(root):
        if n["text"] or n["desc"] or "Edit" in n["class"] or n["click"] == "true":
            print(
                f"{n['class'].split('.')[-1]:22} click={n['click']} {n['bounds']:24} "
                f"desc={n['desc']!r:40} text={n['text']!r}"
            )


def find(root: ET.Element, *, text: str | None = None, desc: str | None = None, cls: str | None = None, contains: str | None = None):
    for n in iter_nodes(root):
