def clear_focused_field(n_dels: int = 80) -> None:
    # Ir al final y borrar.
    key("KEYCODE_MOVE_END")
    for _ in range(n_dels):
        key("KEYCODE_DEL")


def type_ascii(text: str) -> None:
    """Escribe texto vía `input text`. Espacios = %s; el resto se escapa lo mínimo."""
    if not text:
        return
    escaped = text.replace(" ", "%s").replace("'", "'\\''")
    adb("shell", f"input text '{escaped}'")


def paste_via_emu_clipboard(text: str) -> None:
    subprocess.run(
        ["adb", "-s", SERIAL, "emu", "clipboard", text],
        check=False,
        capture_output=True,
        timeout=10,
    )
    time.sleep(0.15)
    key(279)  # KEYCODE_PASTE


def fill_field(root: ET.Element, *, desc: str, value: str, clear: bool = True) -> None:
    n = find(root, desc=desc) or find(root, text=desc)
    if n is None:
        raise RuntimeError(f"no encuentro campo {desc!r}")
    tap_node(n)
    time.sleep(0.25)
    if clear:
        clear_focused_field()
    # Preferir clipboard del emulador: admite @ y puntos.
    paste_via_emu_clipboard(value)
    time.sleep(0.2)


def hide_keyboard() -> None:
    key("KEYCODE_BACK")
    time.sleep(0.3)


def visible_blob(root: ET.Element) -> str:
    return "\n".join(texts(root))


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "dump"
    if cmd == "dump":
        print_nodes(dump_ui())
    elif cmd == "shot":
        name = sys.argv[2] if len(sys.argv) > 2 else "shot.png"
        print(screenshot(name))
    elif cmd == "tap":
        tap(int(sys.argv[2]), int(sys.argv[3]))
    elif cmd == "text":
        print_nodes(dump_ui())
        print("---BLOB---")
        print(visible_blob(dump_ui()))
    else:
        raise SystemExit(f"comando desconocido: {cmd}")

