const require = createRequire('$SRC_LIVE/package.json');
const { keccak_256 } = require('@noble/hashes/sha3.js');
const ascii = new TextEncoder();
function toChecksum(address) {
  const raw = address.replace(/^0x/i,'').toLowerCase();
  const hash = Buffer.from(keccak_256(ascii.encode(raw))).toString('hex');
  let out = '0x';
  for (let i = 0; i < raw.length; i++) out += parseInt(hash[i], 16) >= 8 ? raw[i].toUpperCase() : raw[i];
  return out;
}
for (const a of ['0x5c9CB52Bcf6C2B8B223Ce9B1E7853a2d12E579B5','0xe7f1725E7734CE288F8367e1Bb143E90bb3F0512']) {
  const c=toChecksum(a);
  console.log(a, c===a ? 'EIP-55 OK' : 'FAIL got '+c);
}
" > evidencia/AT-11-06-eip55.txt
# logcat password scan
echo 'EvalPass12 in logcat:' > evidencia/AT-11-01-11-logcat-scan.txt
(grep -F 'EvalPass12' /tmp/logcat-login-01.txt && echo FOUND || echo NOT_FOUND) >> evidencia/AT-11-01-11-logcat-scan.txt
(grep -iE 'Bearer |EvalPass' /tmp/logcat-login-01.txt | head) >> evidencia/AT-11-01-11-logcat-scan.txt
# console in src
rg -n 'console\.(log|debug|info|warn|error)' sut/mobile/src sut/mobile/App.tsx sut/mobile/index.ts > evidencia/AT-11-01-11-src-console-grep.txt || true
# health
curl -sS "$EXCHANGE_API_URL/health"; echo
ls evidencia | wc -l
ls evidencia
# kill leftover logcat if any
if [ -f /tmp/logcat-login-01.pid ]; then kill $(cat /tmp/logcat-login-01.pid) 2>/dev/null || true; fi

